/bin/bash -c "python - <<'PY'
import numpy as np
p=np.load('source_pixels.npz')['rgb'].astype(int)
f=p[0]
# print pixel color grid labels for x 58..90 y 32..103 (green background G, white/dark object)
for y in range(32,104,2):
 s=''
 for x in range(56,94):
  r,g,b=f[y,x]
  if g>r+8 and g>b+15:
   s+='.'
  elif r+g+b>350:
   s+='W'
  elif r+g+b<220:
   s+='#'
  else:
   s+='o'
 print(f'{y:3d} {s}')
PY"

